DROP DATABASE IF EXISTS smart_healthcare;
CREATE DATABASE smart_healthcare CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_healthcare;
CREATE TABLE roles(role_id INT AUTO_INCREMENT PRIMARY KEY,role_name VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,role_id INT NOT NULL,full_name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(role_id));
CREATE TABLE departments(department_id INT AUTO_INCREMENT PRIMARY KEY,department_name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE patients(patient_id INT AUTO_INCREMENT PRIMARY KEY,patient_code VARCHAR(30) NOT NULL UNIQUE,full_name VARCHAR(120) NOT NULL,birth_date DATE,sex VARCHAR(20),contact_number VARCHAR(30),address VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE doctors(doctor_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,department_id INT NOT NULL,license_number VARCHAR(60) UNIQUE,specialization VARCHAR(100),FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(department_id) REFERENCES departments(department_id));
CREATE TABLE doctor_schedules(schedule_id INT AUTO_INCREMENT PRIMARY KEY,doctor_id INT NOT NULL,day_of_week ENUM('Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday') NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,room VARCHAR(30),FOREIGN KEY(doctor_id) REFERENCES doctors(doctor_id));
CREATE TABLE appointments(appointment_id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT NOT NULL,appointment_datetime DATETIME NOT NULL,status ENUM('Pending','Confirmed','Completed','Cancelled') DEFAULT 'Pending',reason VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(doctor_id) REFERENCES doctors(doctor_id));
CREATE TABLE medical_records(record_id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT NOT NULL,appointment_id INT,diagnosis VARCHAR(255) NOT NULL,notes TEXT,recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(doctor_id) REFERENCES doctors(doctor_id),FOREIGN KEY(appointment_id) REFERENCES appointments(appointment_id));
CREATE TABLE medications(medication_id INT AUTO_INCREMENT PRIMARY KEY,medication_name VARCHAR(120) NOT NULL UNIQUE,description VARCHAR(255));
CREATE TABLE prescriptions(prescription_id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT NOT NULL,appointment_id INT,prescribed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,instructions TEXT,FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(doctor_id) REFERENCES doctors(doctor_id),FOREIGN KEY(appointment_id) REFERENCES appointments(appointment_id));
CREATE TABLE prescription_items(prescription_item_id INT AUTO_INCREMENT PRIMARY KEY,prescription_id INT NOT NULL,medication_id INT NOT NULL,dosage VARCHAR(80) NOT NULL,frequency VARCHAR(80) NOT NULL,duration VARCHAR(80),FOREIGN KEY(prescription_id) REFERENCES prescriptions(prescription_id),FOREIGN KEY(medication_id) REFERENCES medications(medication_id));
CREATE TABLE invoices(invoice_id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,appointment_id INT,invoice_date DATE NOT NULL,total_amount DECIMAL(10,2) DEFAULT 0,status ENUM('Unpaid','Partially Paid','Paid') DEFAULT 'Unpaid',FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(appointment_id) REFERENCES appointments(appointment_id));
CREATE TABLE invoice_items(invoice_item_id INT AUTO_INCREMENT PRIMARY KEY,invoice_id INT NOT NULL,item_description VARCHAR(180) NOT NULL,quantity INT DEFAULT 1,unit_price DECIMAL(10,2) NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(invoice_id));
CREATE TABLE payments(payment_id INT AUTO_INCREMENT PRIMARY KEY,invoice_id INT NOT NULL,amount DECIMAL(10,2) NOT NULL,payment_method VARCHAR(40) NOT NULL,paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES invoices(invoice_id));
CREATE INDEX idx_appt_patient ON appointments(patient_id);
CREATE INDEX idx_appt_doctor ON appointments(doctor_id);
